"""Unified Non Lifers intelligence dashboard: display-only update."""
from pathlib import Path
import base64
root=Path(__file__).resolve().parent
(root/'static/intel.js').write_text(base64.b64decode('').decode('utf-8'), encoding='utf-8')
(root/'templates/intel.html').write_text(base64.b64decode('').decode('utf-8'), encoding='utf-8')
p=root/'static/intel.css'
p.write_text(p.read_text(encoding='utf-8')+'\n'+base64.b64decode('').decode('utf-8'),encoding='utf-8')
print("Unified dashboard assets installed")